contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Try a Collect with arbitrary amount when the stored balance is below MinSum.
    // We take params to set MinSum, deposit some small amount (< MinSum), then call Collect.
    function run(uint setMin, uint depositAmount, uint collectAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(depositAmount > 0);
        require(address(this).balance >= depositAmount);

        // initialize MinSum and Log (LogFile address can be zero; it's only used when actions occur)
        // SetMinSum must be called before Initialized is set; c is fresh per spec.
        c.SetMinSum(setMin); if (__ESBMC_reverted()) return;

        // Make a deposit from this test contract of depositAmount
        // ensure depositAmount < setMin so caller's recorded balance < MinSum
        // If setMin == 0 then the precondition below will fail and revert the test invocation
        require(depositAmount < setMin);

        // perform deposit by sending Ether
        c.Deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        // read balances before calling Collect
        uint before_recorded = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint before_contract_balance = address(c).balance;

        bool reverted;
        c.Collect(collectAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint after_recorded = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint after_contract_balance = address(c).balance;

        // General rule: if the caller's recorded balance was strictly less than MinSum before the call,
        // then Collect must not succeed in transferring funds or changing stored balances.
        // That means: call either reverts or returns without changing recorded or contract balances.
        assert(before_recorded < c.MinSum() ? (after_recorded == before_recorded && after_contract_balance == before_contract_balance) : true);
    }

    // allow receiving Ether so the test contract can fund deposits
    receive() external payable {}
}

