// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function _run(uint256 setMin, uint256 depositAmount, uint256 collectAmount) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(depositAmount > 0);
        vm.assume(address(this).balance >= depositAmount);
        try c.SetMinSum(setMin) {} catch { return; }
        vm.assume(depositAmount < setMin);
        try c.Deposit{value: depositAmount}() {} catch { return; }
        uint256 before_recorded;
        try c.balances(address(this)) returns (uint256 __r) { before_recorded = __r; } catch { return; }
        uint before_contract_balance = address(c).balance;
        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 after_recorded;
        try c.balances(address(this)) returns (uint256 __r) { after_recorded = __r; } catch { return; }
        uint after_contract_balance = address(c).balance;
        assertTrue(before_recorded < c.MinSum() ? (after_recorded == before_recorded && after_contract_balance == before_contract_balance) : true);
    }

    function testFuzz_run(uint256 setMin, uint256 depositAmount, uint256 collectAmount) public {
        _run(setMin, depositAmount, collectAmount);
    }

    receive() external payable {}
}
